SELECT pc.product_code, p.name AS product_name, pc.stock, pc.stock_unlimited, pc.sale_limit, pc.price02, pc.delivery_fee, pc.sale_type_id, st.name AS sale_type_name FROM dtb_product_class pc INNER JOIN dtb_product p ON p.id = pc.product_id LEFT JOIN mtb_sale_type st ON st.id = pc.sale_type_id WHERE pc.product_code = :productCode AND pc.class_category_id1 IS NULL AND pc.class_category_id2 IS NULL ORDER BY pc.id ASC LIMIT 1
